/* com.lsy.sicore_v1.menu.mapper.MenuMapper.insertMenu [메뉴 등록] */
INSERT INTO TB_MENU
(
      MENU_ID
    , MENU_NAME
    , PARENT_MENU_ID
    , MENU_LEVEL
    , SORT_ORDER
    , MENU_URL
    , CREATED_AT
    , UPDATED_AT
)
VALUES
(
      #{menuId}
    , #{menuName}
    , #{parentMenuId}
    , #{menuLevel}
    , #{sortOrder}
    , #{menuUrl}
    , SYSDATE
    , SYSDATE
)

mapper.update:
/* com.lsy.sicore_v1.menu.mapper.MenuMapper.deleteMenu [메뉴 사용 중지] */
UPDATE TB_MENU
   SET USE_YN = 'N'
   WHERE MENU_ID = #{menuId}
